	const csrf_token = await helpers.getCsrfToken(jar);
	const { response, body } = await request.post(`${nconf.get('url')}/logout`, {
		body: {},
		jar,
		headers: {
			'x-csrf-token': csrf_token,
		},
	});
	return { response, body };
};

